package io.github.hemanthvk980.shortener.service;

import java.net.InetAddress;
import java.net.URI;
import java.util.Locale;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

@Component
public class UrlValidator {
    private final String ownHost;

    public UrlValidator(@Value("${app.base-url}") String baseUrl) {
        this.ownHost = URI.create(baseUrl).getHost();
    }

    public String validate(String raw) {
        URI uri;
        try {
            uri = new URI(raw.strip());
        } catch (Exception e) {
            throw new IllegalArgumentException("url is not well-formed");
        }
        String scheme = uri.getScheme() == null ? "" : uri.getScheme().toLowerCase(Locale.ROOT);
        if (!scheme.equals("http") && !scheme.equals("https")) throw new IllegalArgumentException("only http and https urls are allowed");
        if (uri.getUserInfo() != null) throw new IllegalArgumentException("credentials in url are not allowed");
        String host = uri.getHost();
        if (host == null) throw new IllegalArgumentException("url must have a host");
        host = host.toLowerCase(Locale.ROOT);
        if (host.equals("localhost") || host.equalsIgnoreCase(ownHost)) throw new IllegalArgumentException("host not allowed");
        if (host.matches("^[0-9.]+$") || host.startsWith("[")) {
            try {
                InetAddress a = InetAddress.getByName(host.replace("[", "").replace("]", ""));
                if (a.isLoopbackAddress() || a.isSiteLocalAddress() || a.isLinkLocalAddress() || a.isAnyLocalAddress()) {
                    throw new IllegalArgumentException("private addresses are not allowed");
                }
            } catch (java.net.UnknownHostException e) {
                throw new IllegalArgumentException("invalid address");
            }
        }
        return uri.toString();
    }
}

package io.github.hemanthvk980.shortener.service;

import io.github.hemanthvk980.shortener.domain.ClickEvent;
import io.github.hemanthvk980.shortener.domain.Link;
import io.github.hemanthvk980.shortener.repo.ClickEventRepository;
import io.github.hemanthvk980.shortener.repo.LinkRepository;
import java.security.SecureRandom;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneOffset;
import java.util.List;
import java.util.NoSuchElementException;
import org.springframework.scheduling.annotation.Async;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class LinkService {
    private static final String ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    private final SecureRandom random = new SecureRandom();
    private final LinkRepository links;
    private final ClickEventRepository clicks;
    private final UrlValidator validator;

    public LinkService(LinkRepository links, ClickEventRepository clicks, UrlValidator validator) {
        this.links = links;
        this.clicks = clicks;
        this.validator = validator;
    }

    @Transactional
    public Link create(String url) {
        String target = validator.validate(url);
        for (int i = 0; i < 5; i++) {
            String code = nextCode();
            if (!links.existsByCode(code)) return links.save(new Link(code, target, Instant.now()));
        }
        throw new IllegalStateException("could not allocate a code");
    }

    @Transactional(readOnly = true)
    public Link resolve(String code) {
        return links.findByCode(code).orElseThrow(() -> new NoSuchElementException("no link " + code));
    }

    @Async
    @Transactional
    public void recordClick(Long linkId) {
        clicks.save(new ClickEvent(linkId, Instant.now()));
        links.incrementClicks(linkId);
    }

    @Transactional(readOnly = true)
    public List<ClickEventRepository.Daily> daily(Link link) {
        return clicks.countByDay(link.getId(), LocalDate.now(ZoneOffset.UTC).minusDays(29));
    }

    private String nextCode() {
        char[] c = new char[7];
        for (int i = 0; i < c.length; i++) c[i] = ALPHABET.charAt(random.nextInt(ALPHABET.length()));
        return new String(c);
    }
}

package io.github.hemanthvk980.shortener.web;

import io.github.hemanthvk980.shortener.domain.Link;
import io.github.hemanthvk980.shortener.service.LinkService;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import java.net.URI;
import java.util.List;
import java.util.Map;
import java.util.NoSuchElementException;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1/links")
public class LinkController {
    public record CreateLinkRequest(@NotBlank String url) {}

    public record LinkResponse(String code, String shortUrl, String targetUrl) {}

    private final LinkService service;
    private final String baseUrl;

    public LinkController(LinkService service, @Value("${app.base-url}") String baseUrl) {
        this.service = service;
        this.baseUrl = baseUrl.endsWith("/") ? baseUrl : baseUrl + "/";
    }

    @PostMapping
    public ResponseEntity<LinkResponse> create(@Valid @RequestBody CreateLinkRequest req) {
        Link l = service.create(req.url());
        return ResponseEntity.created(URI.create("/api/v1/links/" + l.getCode()))
                .body(new LinkResponse(l.getCode(), baseUrl + l.getCode(), l.getTargetUrl()));
    }

    @GetMapping("/{code}/stats")
    public Map<String, Object> stats(@PathVariable String code) {
        Link l = service.resolve(code);
        List<?> daily = service.daily(l);
        return Map.of("code", code, "totalClicks", l.getClickCount(), "clicksByDay", daily);

    @ExceptionHandler(IllegalArgumentException.class)
    ProblemDetail badRequest(IllegalArgumentException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, e.getMessage());
    }

    @ExceptionHandler(NoSuchElementException.class)
    ProblemDetail notFound(NoSuchElementException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }
}

package io.github.hemanthvk980.shortener.web;

import io.github.hemanthvk980.shortener.domain.Link;
import io.github.hemanthvk980.shortener.service.LinkService;
import java.net.URI;
import java.util.NoSuchElementException;
import org.springframework.http.CacheControl;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
public class RedirectController {
    private final LinkService service;

    public RedirectController(LinkService service) {
        this.service = service;
    }

    @GetMapping("/{code:[A-Za-z0-9]+}")
    public ResponseEntity<Void> redirect(@PathVariable String code) {
        Link l = service.resolve(code);
        service.recordClick(l.getId());
        return ResponseEntity.status(HttpStatus.FOUND).location(URI.create(l.getTargetUrl()))
                .cacheControl(CacheControl.noStore()).build();
    }

    @ExceptionHandler(NoSuchElementException.class)
    ProblemDetail notFound(NoSuchElementException e) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, e.getMessage());
    }
}
